const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Africa geometry
  const africa = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017')
    .filter(ee.Filter.inList('wld_rgn', ['Africa']));
  const africaGeom = africa.geometry();

  // Use MODIS Land Cover Type Yearly Global 500m
  const modisLC = ee.ImageCollection('MODIS/006/MCD12Q1')
    .select('LC_Type1');

  // Get images for both periods
  const img2004 = modisLC.filter(ee.Filter.date('2004-01-01', '2004-12-31')).first();
  const img2007 = modisLC.filter(ee.Filter.date('2007-01-01', '2007-12-31')).first();
  const img2016 = modisLC.filter(ee.Filter.date('2016-01-01', '2016-12-31')).first();
  const img2019 = modisLC.filter(ee.Filter.date('2019-01-01', '2019-12-31')).first();

  // Check if images exist
  const count2004 = modisLC.filter(ee.Filter.date('2004-01-01', '2004-12-31')).size().getInfo();
  const count2007 = modisLC.filter(ee.Filter.date('2007-01-01', '2007-12-31')).size().getInfo();
  const count2016 = modisLC.filter(ee.Filter.date('2016-01-01', '2016-12-31')).size().getInfo();
  const count2019 = modisLC.filter(ee.Filter.date('2019-01-01', '2019-12-31')).size().getInfo();

  console.log(`Images found - 2004: ${count2004}, 2007: ${count2007}, 2016: ${count2016}, 2019: ${count2019}`);

  if (count2004 === 0 || count2007 === 0 || count2016 === 0 || count2019 === 0) {
    console.log('Missing data for one or more years');
    console.log('<answer>C1</answer>');
    return;
  }

  // MODIS LC_Type1: Croplands = 12, Cropland/Natural Vegetation Mosaic = 14
  const croplandMask2004 = img2004.eq(12).or(img2004.eq(14));
  const croplandMask2007 = img2007.eq(12).or(img2007.eq(14));
  const croplandMask2016 = img2016.eq(12).or(img2016.eq(14));
  const croplandMask2019 = img2019.eq(12).or(img2019.eq(14));

  // Calculate cropland area in km² for each year
  const pixelArea = ee.Image.pixelArea().divide(1e6); // Convert to km²

  const area2004 = croplandMask2004.multiply(pixelArea).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: africaGeom,
    scale: 5000,
    maxPixels: 1e9
  }).get('LC_Type1').getInfo();

  const area2007 = croplandMask2007.multiply(pixelArea).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: africaGeom,
    scale: 5000,
    maxPixels: 1e9
  }).get('LC_Type1').getInfo();

  const area2016 = croplandMask2016.multiply(pixelArea).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: africaGeom,
    scale: 5000,
    maxPixels: 1e9
  }).get('LC_Type1').getInfo();

  const area2019 = croplandMask2019.multiply(pixelArea).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: africaGeom,
    scale: 5000,
    maxPixels: 1e9
  }).get('LC_Type1').getInfo();

  console.log(`Cropland area (km²) - 2004: ${Math.round(area2004)}, 2007: ${Math.round(area2007)}`);
  console.log(`Cropland area (km²) - 2016: ${Math.round(area2016)}, 2019: ${Math.round(area2019)}`);

  if (area2004 === null || area2007 === null || area2016 === null || area2019 === null) {
    console.log('Calculation returned null values');
    console.log('<answer>C3</answer>');
    return;
  }

  if (area2004 === 0 || area2007 === 0 || area2016 === 0 || area2019 === 0) {
    console.log('No valid cropland pixels detected');
    console.log('<answer>C2</answer>');
    return;
  }

  // Calculate annual rates of change
  const period1Years = 3; // 2004 to 2007
  const period2Years = 3; // 2016 to 2019

  const rate1 = (area2007 - area2004) / period1Years; // km²/year
  const rate2 = (area2019 - area2016) / period2Years; // km²/year

  console.log(`Annual expansion rate 2004-2007: ${Math.round(rate1)} km²/year`);
  console.log(`Annual expansion rate 2016-2019: ${Math.round(rate2)} km²/year`);

  // Check if expansion rate slowed
  if (rate2 < rate1) {
    console.log('Expansion rate slowed in 2016-2019');
    console.log('<answer>A</answer>');
  } else {
    console.log('Expansion rate did not slow in 2016-2019');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
